// Arma la consulta para Gemini con todo lo que AssistentD sabe de la persona
const c = $input.first().json.ctx || {};

if (!c.clave) {
  return [{ json: { fase: 'fallo', texto: 'Todavía no tengo una clave de Gemini. Abre "Sobre ti" y pulsa "Cambiar clave de Gemini".' } }];
}

const p = c.perfil || {};
const llamar = p.como_llamar || p.nombre || 'la persona';

// 1) Estilo observado en sus mensajes
const estilo = [];
if ((p.mensajes_vistos || 0) >= 2) {
  if (p.formalidad > 0.65) estilo.push('Escribe con cortesía formal: trátale de usted y cuida la redacción.');
  else if (p.formalidad < 0.35) estilo.push('Escribe relajado y coloquial, como alguien de confianza; tutéale.');
  else estilo.push('Tono cercano y neutro; tutéale salvo que pida lo contrario.');
  if (p.largo_promedio < 45) estilo.push('Sus mensajes son cortos: contesta breve (2 a 4 líneas) salvo que pida detalle.');
  else if (p.largo_promedio > 140) estilo.push('Escribe mensajes largos: puedes explicar con más detalle.');
  if (p.emojis > 0.4) estilo.push('Usa emojis con frecuencia, igual que la persona.');
  else if (p.emojis < 0.1) estilo.push('No uses emojis.');
  else estilo.push('Algún emoji ocasional está bien.');
  if (p.entusiasmo > 0.5) estilo.push('Responde con energía y entusiasmo.');
} else {
  estilo.push('Aún no conoces su estilo: sé cálido, claro y breve, tuteando.');
}

const prefs = Object.entries(p.preferencias || {}).map(([k, v]) => `- ${k}: ${v}`);
const recuerdos = (c.recuerdos || []).map((r) => `- [${r.id}] (${r.tema}) ${r.dato}`);
const proximos = (c.proximos || []).map((e) =>
  `- [${e.id}] ${e.dia} ${e.fecha} ${e.hora}-${e.hora_fin} ${e.titulo} (${e.categoria}, prioridad ${e.prioridad}${e.repeticion !== 'no' ? ', se repite ' + e.repeticion : ''})`);
const tareas = (c.tareas || []).map((t) => `- [${t.id}] ${t.texto} (prioridad ${t.prioridad}${t.limite ? ', para ' + t.limite : ''})`);

const sistema = `Eres AssistentD, el asistente personal que vive en la computadora de ${llamar}. Llevas su agenda, recuerdas lo que te cuenta y te adaptas a su manera de ser. No eres un buscador ni un chatbot genérico.

MOMENTO ACTUAL
Hoy es ${c.hoy} ${c.ahora} (zona ${c.zona}).
Próximos 14 días: ${(c.calendario || []).join(', ')}.
Usa esa lista para convertir "mañana", "el jueves" o "la otra semana" en fechas exactas. No adivines días de la semana.

QUIÉN ES
Nombre: ${p.nombre || 'sin indicar'}. Llámale "${llamar}" de vez en cuando, sin exagerar.
${p.sobre_mi ? 'Se presentó así: ' + p.sobre_mi : ''}
Lo que has aprendido de esta persona:
${recuerdos.join('\n') || '- (todavía nada)'}

CÓMO HABLARLE (aprendido de sus mensajes)
${estilo.join('\n')}
${prefs.length ? 'Preferencias que pidió de forma explícita (mandan sobre lo anterior):\n' + prefs.join('\n') : ''}

AGENDA DE LOS PRÓXIMOS 7 DÍAS (el número entre corchetes es el id)
${proximos.join('\n') || '- Nada agendado.'}

PENDIENTES ABIERTOS
${tareas.join('\n') || '- Ninguno.'}

FORMA DE TRABAJAR
1. Para guardar, mover o cancelar algo usa siempre las herramientas. Solo confirma un cambio si la herramienta respondió guardado, editado o cancelado en true.
2. Si falta el día o la hora de una actividad, pregunta antes de guardar. Si no dice cuánto dura, usa 60 minutos. Si no dice cuándo avisar, usa 20 minutos.
3. Si crear_evento o editar_evento responde "choque de horario", explica con qué se cruza y ofrece los huecos sugeridos. Usa forzar=true solo si la persona acepta el cruce.
4. Si la fecha ya pasó, avísale y pregunta si quiso decir otra.
5. Para editar o cancelar necesitas el id. Si no está en la agenda de arriba, búscalo con listar_eventos (puedes usar "buscar"). Si hay varias coincidencias, pregunta cuál.
6. Elige categoría y prioridad con criterio: exámenes, entregas y citas médicas van con prioridad 1.
7. Lo que no tiene hora fija ("tengo que comprar...", "pendiente: ...") es una tarea: usa agregar_tarea. Las ideas o datos para guardar son notas: guardar_nota.
8. Cuando la persona cuente algo estable sobre sí misma (gustos, rutina, estudios, trabajo, personas cercanas, metas) guárdalo con recordar_dato, en pocas palabras y en tercera persona, sin pedir permiso. No guardes salud, dinero ni temas delicados. No repitas lo que ya sabes.
9. Si pide que cambies tu forma de hablar ("más corto", "sin emojis", "háblame de usted", "con más humor"), usa ajustar_personalidad y aplícalo desde esta misma respuesta. Si pide que le llames distinto, usa cambiar_nombre.
10. Al confirmar una actividad di título, día de la semana, fecha (DD/MM), hora y con cuánto aviso. Al mostrar la agenda agrupa por día con listas cortas.
11. Si ves un día recargado, una entrega cerca o mucho tiempo libre antes de un examen, sugiérelo con tacto, sin sermones.
12. Puedes conversar de cualquier tema y ayudar con dudas, pero tu fuerte es organizar su tiempo.
13. Responde siempre en español, en texto simple. Puedes usar **negritas** y listas con "- ". No uses tablas ni títulos con #.`;

// 2) Historial: Gemini espera que la conversación empiece con la persona
const contents = [];
for (const m of c.historial || []) {
  const role = m.rol === 'persona' ? 'user' : 'model';
  if (!contents.length && role === 'model') continue;
  const ultimo = contents[contents.length - 1];
  if (ultimo && ultimo.role === role) ultimo.parts[0].text += '\n' + m.texto;
  else contents.push({ role, parts: [{ text: m.texto }] });
}
const entrada = String(c.entrada || '').trim() || 'Hola';
if (contents.length && contents[contents.length - 1].role === 'user') contents[contents.length - 1].parts[0].text += '\n' + entrada;
else contents.push({ role: 'user', parts: [{ text: entrada }] });

// 3) Herramientas que puede pedir (las ejecuta la base de datos)
const S = (description, extra = {}) => ({ type: 'STRING', description, ...extra });
const N = (description) => ({ type: 'INTEGER', description });
const B = (description) => ({ type: 'BOOLEAN', description });
const camposEvento = {
  titulo: S('Título corto, por ejemplo "Examen de Física"'),
  inicio: S('Fecha y hora de inicio en formato AAAA-MM-DD HH:MM (24 horas, hora local)'),
  duracion_min: N('Duración en minutos. 60 si no se indica'),
  detalle: S('Detalles extra: lugar, qué llevar, etc.'),
  categoria: S('Tipo de actividad', { enum: ['estudio', 'trabajo', 'personal', 'salud', 'social', 'tramite'] }),
  prioridad: N('1 alta, 2 media, 3 baja'),
  repeticion: S('Si se repite', { enum: ['no', 'diaria', 'laborables', 'semanal', 'mensual'] }),
  repetir_hasta: S('Último día de la repetición, AAAA-MM-DD. Vacío si no termina'),
  aviso_min: N('Minutos antes para avisar. 0 para avisar solo al empezar'),
  forzar: B('true solo si la persona aceptó guardarlo aunque choque con otra actividad'),
};
const herramientas = [
  { name: 'crear_evento', description: 'Agenda una actividad con fecha y hora. Revisa choques de horario antes de guardar.',
    parameters: { type: 'OBJECT', properties: camposEvento, required: ['titulo', 'inicio'] } },
  { name: 'listar_eventos', description: 'Lista las actividades entre dos fechas, incluyendo las repetitivas.',
    parameters: { type: 'OBJECT', properties: {
      desde: S('Inicio AAAA-MM-DD o AAAA-MM-DD HH:MM'), hasta: S('Fin AAAA-MM-DD (incluye ese día completo)'),
      buscar: S('Texto para filtrar por título o detalle') } } },
  { name: 'editar_evento', description: 'Cambia una actividad existente. Envía solo los campos que cambian.',
    parameters: { type: 'OBJECT', properties: { id: N('Id de la actividad'), ...camposEvento }, required: ['id'] } },
  { name: 'cancelar_evento', description: 'Quita una actividad de la agenda (si es repetitiva, quita toda la serie).',
    parameters: { type: 'OBJECT', properties: { id: N('Id de la actividad') }, required: ['id'] } },
  { name: 'buscar_huecos', description: 'Busca espacios libres en un día para encajar algo de cierta duración.',
    parameters: { type: 'OBJECT', properties: {
      dia: S('Día AAAA-MM-DD'), duracion_min: N('Minutos que necesita'),
      desde_hora: S('Hora mínima HH:MM, por defecto 07:00'), hasta_hora: S('Hora máxima HH:MM, por defecto 21:00') }, required: ['dia'] } },
  { name: 'resumen_dia', description: 'Resumen de un día: actividades, tareas que vencen y espacios libres.',
    parameters: { type: 'OBJECT', properties: { dia: S('Día AAAA-MM-DD; hoy si se omite') } } },
  { name: 'agregar_tarea', description: 'Anota un pendiente sin hora fija.',
    parameters: { type: 'OBJECT', properties: { texto: S('Qué hay que hacer'), prioridad: N('1 alta, 2 media, 3 baja'), limite: S('Fecha límite AAAA-MM-DD, opcional') }, required: ['texto'] } },
  { name: 'listar_tareas', description: 'Lista los pendientes abiertos.',
    parameters: { type: 'OBJECT', properties: { incluir_hechas: B('true para incluir los terminados esta semana') } } },
  { name: 'completar_tarea', description: 'Marca un pendiente como hecho (o lo reabre con deshacer=true).',
    parameters: { type: 'OBJECT', properties: { id: N('Id del pendiente'), deshacer: B('true para reabrirlo') }, required: ['id'] } },
  { name: 'borrar_tarea', description: 'Elimina un pendiente.',
    parameters: { type: 'OBJECT', properties: { id: N('Id del pendiente') }, required: ['id'] } },
  { name: 'guardar_nota', description: 'Guarda una nota rápida (ideas, datos, listas).',
    parameters: { type: 'OBJECT', properties: { texto: S('Contenido de la nota') }, required: ['texto'] } },
  { name: 'buscar_notas', description: 'Busca entre las notas guardadas.',
    parameters: { type: 'OBJECT', properties: { buscar: S('Texto a buscar; vacío para ver las últimas') } } },
  { name: 'borrar_nota', description: 'Elimina una nota.',
    parameters: { type: 'OBJECT', properties: { id: N('Id de la nota') }, required: ['id'] } },
  { name: 'recordar_dato', description: 'Guarda algo estable que aprendiste de la persona.',
    parameters: { type: 'OBJECT', properties: {
      tema: S('Tema', { enum: ['general', 'gustos', 'rutina', 'estudios', 'trabajo', 'personas', 'metas'] }),
      dato: S('El dato en una frase corta en tercera persona') }, required: ['tema', 'dato'] } },
  { name: 'olvidar_dato', description: 'Borra algo que habías aprendido, si la persona lo pide o ya no es cierto.',
    parameters: { type: 'OBJECT', properties: { id: N('Id del dato') }, required: ['id'] } },
  { name: 'ajustar_personalidad', description: 'Guarda cómo quiere la persona que le hables.',
    parameters: { type: 'OBJECT', properties: {
      aspecto: S('Qué se ajusta: largo, trato, emojis, humor, tono u otro'),
      preferencia: S('La preferencia en pocas palabras, ej. "respuestas muy cortas". Vacío para quitarla') }, required: ['aspecto'] } },
  { name: 'cambiar_nombre', description: 'Cambia cómo llamar a la persona.',
    parameters: { type: 'OBJECT', properties: { como_llamar: S('Nombre o apodo') }, required: ['como_llamar'] } },
];

const peticion = {
  systemInstruction: { parts: [{ text: sistema }] },
  contents,
  tools: [{ functionDeclarations: herramientas }],
  generationConfig: { temperature: 0.7, maxOutputTokens: 8192 },
};

return [{ json: {
  fase: 'pensar',
  api: 'https://generativelanguage.googleapis.com/v1beta',
  clave: c.clave,
  modelos: (c.modelos && c.modelos.length) ? c.modelos : ['gemini-2.5-flash', 'gemini-2.5-flash-lite'],
  modelo_idx: 0,
  vueltas: 0,
  hubo_cambios: false,
  peticion,
} }];

// Envía la conversación a Gemini y decide qué sigue:
// usar herramientas (vuelve a la base de datos) o responder.
let e = $input.first().json;
if (e.estado) e = e.estado;           // viene de "Usar herramientas"
if (e.fase === 'fallo') return [{ json: e }];

// Resultados de las herramientas de la vuelta anterior
if (Array.isArray(e.resultados) && e.resultados.length) {
  e.peticion.contents.push({
    role: 'user',
    parts: e.resultados.map((r) => ({
      functionResponse: { name: r.name, ...(r.id ? { id: r.id } : {}), response: { resultado: r.resultado } },
    })),
  });
}
delete e.resultados;
e.vueltas = (e.vueltas || 0) + 1;
if (e.vueltas > 8) {
  return [{ json: { fase: 'respuesta', texto: 'Me enredé con esa petición. ¿Me la dices de otra forma, por partes?', hubo_cambios: !!e.hubo_cambios } }];
}

const motivo = (cuerpo) => (cuerpo && cuerpo.error && cuerpo.error.message) || '';
let r = null;
let problema = '';
while (e.modelo_idx < e.modelos.length) {
  const modelo = e.modelos[e.modelo_idx];
  try {
    r = await this.helpers.httpRequest({
      method: 'POST',
      url: `${e.api}/models/${modelo}:generateContent`,
      headers: { 'x-goog-api-key': e.clave, 'Content-Type': 'application/json' },
      body: e.peticion,
      json: true,
      timeout: 90000,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
  } catch (err) {
    r = null;
    problema = 'red';
  }
  if (r && r.statusCode === 200) break;
  if (r) problema = r.statusCode + ' ' + motivo(r.body);
  // Límite gratuito, saturación o modelo retirado: se prueba el siguiente modelo
  if (!r || [404, 429, 500, 503].includes(r.statusCode)) { e.modelo_idx += 1; continue; }
  break;
}

if (!r || r.statusCode !== 200) {
  let texto = 'Gemini no respondió esta vez. Inténtalo de nuevo en un momento.';
  if (problema === 'red') texto = 'No pude conectarme con Gemini. Revisa la conexión a internet.';
  else if (/API_KEY|API key|PERMISSION|403|401/i.test(problema)) texto = 'Tu clave de Gemini no funciona. Ve a "Sobre ti" y cámbiala.';
  else if (/^429/.test(problema)) texto = 'Llegaste al límite gratuito de Gemini por ahora. Espera un minuto y vuelve a intentarlo.';
  return [{ json: { fase: 'fallo', texto, detalle: problema } }];
}

const candidato = (r.body.candidates || [])[0] || {};
const partes = (candidato.content && candidato.content.parts) || [];
const llamadas = partes
  .filter((p) => p.functionCall)
  .map((p) => ({ name: p.functionCall.name, args: p.functionCall.args || {}, id: p.functionCall.id || null }));

if (llamadas.length) {
  e.peticion.contents.push(candidato.content);   // se devuelve tal cual (incluye firmas de razonamiento)
  return [{ json: { ...e, fase: 'herramientas', llamadas } }];
}

let texto = partes.filter((p) => p.text && !p.thought).map((p) => p.text).join('').trim();
if (!texto) {
  texto = candidato.finishReason === 'SAFETY'
    ? 'Prefiero no responder a eso. ¿Te ayudo con otra cosa?'
    : 'Listo. ¿Algo más?';
}
return [{ json: { fase: 'respuesta', texto, hubo_cambios: !!e.hubo_cambios, modelo: e.modelos[e.modelo_idx] } }];
